ALTER TABLE public.biz_approval_workflows DROP CONSTRAINT biz_approval_workflows_kind_check;
ALTER TABLE public.biz_approval_workflows ADD CONSTRAINT biz_approval_workflows_kind_check CHECK(kind IN ('goal_year','report_month','report_quarter','report_year','late_plan_month','late_plan_quarter','late_plan_year','late_report_month','late_report_quarter','late_report_year'));
ALTER TABLE public.biz_late_requests ADD COLUMN department_id uuid REFERENCES public.biz_departments(id),ADD COLUMN revision integer NOT NULL DEFAULT 0;
DO $$DECLARE d text;BEGIN
SELECT pg_get_functiondef('public.biz_workflow_save(jsonb)'::regprocedure) INTO d;d:=replace(d,'''goal_year'',''report_month'',''report_quarter'',''report_year''','''goal_year'',''report_month'',''report_quarter'',''report_year'',''late_plan_month'',''late_plan_quarter'',''late_plan_year'',''late_report_month'',''late_report_quarter'',''late_report_year''');d:=replace(d,'AND public.biz_can(id,CASE WHEN kind_=''goal_year'' THEN ''biz.goal_approve'' ELSE ''biz.report_approve'' END)','');EXECUTE d;
SELECT pg_get_functiondef('public.biz_approval_start(uuid,text,uuid,uuid,jsonb)'::regprocedure) INTO d;d:=replace(d,'AND public.biz_can(id,permission_)','');d:=replace(d,'WHERE user_id=_owner AND ended_at IS NULL','WHERE user_id=_owner AND started_at<=now() AND (ended_at IS NULL OR ended_at>now())');EXECUTE d;
SELECT pg_get_functiondef('public.biz_workflow_preview(jsonb)'::regprocedure) INTO d;d:=replace(d,'AND public.biz_can(id,perm)','');EXECUTE d;
END$$;
CREATE FUNCTION public.biz_late_can_act(_request uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.biz_late_requests l JOIN public.biz_approval_runs r ON r.version_id=l.id AND r.kind='late_'||l.kind||'_'||l.period_kind JOIN public.profiles p ON p.id=auth.uid() WHERE l.id=_request AND l.status='pending' AND r.status='pending' AND p.status='Đang hoạt động' AND r.owner_id<>auth.uid() AND public.biz_run_assigned(l.id,true) AND public.biz_step_scope_ok(r.steps,r.current_step,auth.uid(),r.owner_id,r.department_id,r.submitted_at) AND public.biz_deadline_phase(l.kind||'_'||l.period_kind,l.year,l.period,now())='overdue')$$;
CREATE OR REPLACE FUNCTION public.biz_late_request_create(_kind text,_period_kind text,_year int,_period int,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE id_ uuid;dep uuid;run_ uuid;BEGIN
IF _kind NOT IN ('plan','report') OR NOT public.biz_can(auth.uid(),'biz.'||_kind||'_submit') THEN RAISE EXCEPTION 'Không có quyền nộp tài liệu.';END IF;
PERFORM public.biz_period_start(_year,_period_kind,_period);IF btrim(coalesce(_reason,''))='' THEN RAISE EXCEPTION 'Cần nhập lý do xin nộp bù.';END IF;
PERFORM public.biz_late_expire_closed();IF public.biz_deadline_phase(_kind||'_'||_period_kind,_year,_period,now())<>'overdue' THEN RAISE EXCEPTION 'Kỳ không ở giai đoạn xin nộp bù.';END IF;
IF EXISTS(SELECT 1 FROM public.biz_documents WHERE user_id=auth.uid() AND kind=_kind AND period_kind=_period_kind AND year=_year AND period=_period AND first_submitted_at IS NOT NULL) THEN RAISE EXCEPTION 'Bạn đã nộp hồ sơ kỳ này.';END IF;
dep:=public.biz_period_department(auth.uid(),_year,_period_kind,_period);IF dep IS NULL THEN RAISE EXCEPTION 'Bạn không thuộc phòng trong kỳ này.';END IF;
INSERT INTO public.biz_late_requests(user_id,kind,period_kind,year,period,reason,department_id) VALUES(auth.uid(),_kind,_period_kind,_year,_period,btrim(_reason),dep) RETURNING id INTO id_;
run_:=public.biz_approval_start(id_,'late_'||_kind||'_'||_period_kind,auth.uid(),dep,jsonb_build_object('request_id',id_,'year',_year,'period_kind',_period_kind,'period',_period,'reason',btrim(_reason),'items','[]'::jsonb));IF run_ IS NULL THEN RAISE EXCEPTION 'Chưa cấu hình quy trình duyệt yêu cầu nộp bù.';END IF;RETURN id_;END$$;
CREATE OR REPLACE FUNCTION public.biz_late_request_decide(_id uuid,_approve boolean,_comment text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE l public.biz_late_requests;r public.biz_approval_runs;final_ boolean;BEGIN
SELECT * INTO l FROM public.biz_late_requests WHERE id=_id FOR UPDATE;SELECT * INTO r FROM public.biz_approval_runs WHERE version_id=_id AND kind='late_'||l.kind||'_'||l.period_kind FOR UPDATE;
IF r.id IS NULL THEN RAISE EXCEPTION 'Yêu cầu cũ cần quản trị xác nhận chuyển sang quy trình.';END IF;
IF _approve IS NULL OR NOT public.biz_late_can_act(_id) THEN RAISE EXCEPTION 'Không đến lượt, kỳ đã đóng hoặc không được tự duyệt.';END IF;
final_:=public.biz_approval_step(_id,_approve,_comment);
UPDATE public.biz_late_requests SET status=CASE WHEN NOT _approve THEN 'rejected' WHEN final_ THEN 'approved' ELSE 'pending' END,decided_by=CASE WHEN NOT _approve OR final_ THEN auth.uid() END,decided_at=CASE WHEN NOT _approve OR final_ THEN now() END,decision_comment=CASE WHEN NOT _approve OR final_ THEN nullif(btrim(coalesce(_comment,'')),'') END,revision=revision+1 WHERE id=_id;END$$;
CREATE FUNCTION public.biz_late_request_adopt(_id uuid,_confirmed boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE l public.biz_late_requests;id_ uuid;dep uuid;BEGIN
IF NOT _confirmed OR NOT public.biz_workflow_manage() THEN RAISE EXCEPTION 'Cần quyền quản trị và xác nhận chuyển luồng.';END IF;
SELECT * INTO l FROM public.biz_late_requests WHERE id=_id FOR UPDATE;IF l.id IS NULL OR l.status<>'pending' THEN RAISE EXCEPTION 'Chỉ chuyển yêu cầu đang chờ.';END IF;
SELECT id INTO id_ FROM public.biz_approval_runs WHERE version_id=_id;IF id_ IS NOT NULL THEN RETURN id_;END IF;
IF public.biz_deadline_phase(l.kind||'_'||l.period_kind,l.year,l.period,now())<>'overdue' THEN RAISE EXCEPTION 'Kỳ không còn cho phép nộp bù.';END IF;
dep:=public.biz_period_department(l.user_id,l.year,l.period_kind,l.period);id_:=public.biz_approval_start(_id,'late_'||l.kind||'_'||l.period_kind,l.user_id,dep,jsonb_build_object('request_id',_id,'year',l.year,'period_kind',l.period_kind,'period',l.period,'reason',l.reason,'items','[]'::jsonb));IF id_ IS NULL THEN RAISE EXCEPTION 'Chưa cấu hình quy trình nộp bù.';END IF;
UPDATE public.biz_late_requests SET department_id=dep WHERE id=_id;INSERT INTO public.biz_approval_events(run_id,actor_id,action,step,payload) VALUES(id_,auth.uid(),'adopted',0,jsonb_build_object('original_created_at',l.created_at));RETURN id_;END$$;
DO $$DECLARE d text;BEGIN
SELECT pg_get_functiondef('public.biz_approval_step(uuid,boolean,text)'::regprocedure) INTO d;d:=replace(d,'IF NOT public.biz_step_scope_ok','IF r.kind LIKE ''late_%'' AND NOT public.biz_late_can_act(_version) THEN RAISE EXCEPTION ''Không đến lượt xử lý nộp bù.'';END IF;IF NOT public.biz_step_scope_ok');EXECUTE d;
SELECT pg_get_functiondef('public.biz_approval_notify()'::regprocedure) INTO d;d:=replace(d,'k:=CASE WHEN r.status=', 'k:=CASE WHEN r.status=');d:=replace(d,'FOR u IN SELECT DISTINCT id','IF r.kind LIKE ''late_%'' THEN k:=CASE WHEN r.status=''approved'' THEN ''biz_late_approved'' WHEN r.status=''changes'' THEN ''biz_late_rejected'' ELSE ''biz_late_request'' END;END IF;FOR u IN SELECT DISTINCT id');d:=replace(d,'''approval_run_id'',r.id','''request_id'',CASE WHEN r.kind LIKE ''late_%'' THEN r.version_id END,''approval_run_id'',r.id');d:=replace(d,'''kind'',CASE WHEN r.kind=''goal_year'' THEN ''goal'' ELSE ''report'' END','''kind'',CASE WHEN r.kind=''goal_year'' THEN ''goal'' WHEN r.kind LIKE ''late_plan_%'' THEN ''plan'' ELSE ''report'' END');EXECUTE d;
SELECT pg_get_functiondef('public.biz_approvals_read()'::regprocedure) INTO d;d:=replace(d,'''source_revision'',CASE WHEN a.kind=''goal_year''','''source_revision'',CASE WHEN a.kind LIKE ''late_%'' THEN (SELECT revision FROM public.biz_late_requests WHERE id=a.version_id) WHEN a.kind=''goal_year''');d:=replace(d,'''can_act'',a.status=''pending'' AND public.biz_run_assigned(a.version_id,true) AND public.biz_can(auth.uid(),CASE WHEN a.kind=''goal_year'' THEN ''biz.goal_approve'' ELSE ''biz.report_approve'' END)','''can_act'',CASE WHEN a.kind LIKE ''late_%'' THEN public.biz_late_can_act(a.version_id) ELSE a.status=''pending'' AND public.biz_run_assigned(a.version_id,true) AND public.biz_step_scope_ok(a.steps,a.current_step,auth.uid(),a.owner_id,a.department_id,a.submitted_at) AND public.biz_can(auth.uid(),CASE WHEN a.kind=''goal_year'' THEN ''biz.goal_approve'' ELSE ''biz.report_approve'' END) END');EXECUTE d;
SELECT pg_get_functiondef('public.biz_approval_override(uuid,integer,text,text,uuid)'::regprocedure) INTO d;d:=replace(d,'IF r.id IS NULL','IF r.kind LIKE ''late_%'' THEN RAISE EXCEPTION ''Dùng quy trình nộp bù, không can thiệp qua hồ sơ.'';END IF;IF r.id IS NULL');EXECUTE d;
END$$;
CREATE OR REPLACE FUNCTION public.biz_late_requests_read(_kind text DEFAULT NULL,_period_kind text DEFAULT NULL,_year int DEFAULT NULL,_period int DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE result jsonb;BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Cần đăng nhập.';END IF;PERFORM public.biz_late_expire_closed();
SELECT coalesce(jsonb_agg(to_jsonb(l)||jsonb_build_object('employee_name',p.full_name,'decider_name',dp.full_name,'can_decide',public.biz_late_can_act(l.id),'legacy',NOT EXISTS(SELECT 1 FROM public.biz_approval_runs WHERE version_id=l.id),'can_adopt',l.status='pending' AND public.biz_workflow_manage(),'milestones',public.biz_deadline_milestones(l.kind||'_'||l.period_kind,l.year,l.period),'phase',public.biz_deadline_phase(l.kind||'_'||l.period_kind,l.year,l.period,now())) ORDER BY l.created_at DESC),'[]') INTO result FROM public.biz_late_requests l JOIN public.profiles p ON p.id=l.user_id LEFT JOIN public.profiles dp ON dp.id=l.decided_by WHERE (_kind IS NULL OR l.kind=_kind) AND (_period_kind IS NULL OR l.period_kind=_period_kind) AND (_year IS NULL OR l.year=_year) AND (_period IS NULL OR l.period=_period) AND (l.user_id=auth.uid() OR public.biz_all_scope(auth.uid()) OR public.biz_scope_ok(auth.uid(),l.user_id,coalesce(l.department_id,public.biz_period_department(l.user_id,l.year,l.period_kind,l.period))) OR EXISTS(SELECT 1 FROM public.biz_approval_runs r WHERE r.version_id=l.id AND public.biz_run_can_read(r.id)));
RETURN jsonb_build_object('requests',result,'server_now',now());END$$;
DROP POLICY "Late requests read own or scoped" ON public.biz_late_requests;
CREATE POLICY "Late requests read own or scoped" ON public.biz_late_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.biz_all_scope(auth.uid()) OR public.biz_scope_ok(auth.uid(),user_id,coalesce(department_id,public.biz_period_department(user_id,year,period_kind,period))) OR EXISTS(SELECT 1 FROM public.biz_approval_runs r WHERE r.version_id=biz_late_requests.id AND public.biz_run_can_read(r.id)));
REVOKE ALL ON FUNCTION public.biz_approval_start(uuid,text,uuid,uuid,jsonb),public.biz_approval_step(uuid,boolean,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.biz_late_can_act(uuid),public.biz_late_request_adopt(uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.biz_late_can_act(uuid),public.biz_late_request_adopt(uuid,boolean) TO authenticated;
